import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("rate withdraw", () => {
  test("rate withdraw", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "30.00", "from": "2026-03-05"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00", "date": "2026-03-01"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("3.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("2.00");
    await expect(pg_uma.getByTestId("rate-current-A")).toHaveText("30.00");
    await expect(pg_uma.getByTestId("rate-current-B")).toHaveText("5.00");
    await expect(pg_uma.getByTestId("rate-current-C")).toHaveText("n/a");
    await expect(pg_uma.getByTestId("rate-row-A-start").getByTestId("rate-pct")).toHaveText("20.00");
    await expect(pg_uma.getByTestId("rate-row-A-start").getByTestId("rate-version")).toHaveText("2");
    await expect(pg_uma.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-pct")).toHaveText("30.00");
    await expect(pg_uma.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-version")).toHaveText("1");
    await expect(pg_uma.getByTestId("rate-row-B-start").getByTestId("rate-pct")).toHaveText("5.00");
    await expect(pg_uma.getByTestId("rate-row-B-start").getByTestId("rate-version")).toHaveText("1");
    expect(await ui.withdrawRate(pg_uma, "A", "start")).toBe(false);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.withdrawRate(pg_vic, "A", "start")).toBe(true);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("3.00");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("1.00");
    await expect(pg_vic.getByTestId("rate-current-A")).toHaveText("30.00");
    await expect(pg_vic.getByTestId("rate-current-B")).toHaveText("5.00");
    await expect(pg_vic.getByTestId("rate-current-C")).toHaveText("n/a");
    await expect(pg_vic.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-pct")).toHaveText("30.00");
    await expect(pg_vic.getByTestId("rate-row-A-2026-03-05").getByTestId("rate-version")).toHaveText("1");
    await expect(pg_vic.getByTestId("rate-row-B-start").getByTestId("rate-pct")).toHaveText("5.00");
    await expect(pg_vic.getByTestId("rate-row-B-start").getByTestId("rate-version")).toHaveText("1");
    await expect(pg_vic.getByTestId("rate-row-A-start").getByTestId("rate-pct")).toHaveText("10.00");
    await expect(pg_vic.getByTestId("rate-row-A-start").getByTestId("rate-version")).toHaveText("1");
    expect(await ui.withdrawRate(pg_vic, "A", "start")).toBe(true);
    expect(await ui.withdrawRate(pg_vic, "A", "2026-03-05")).toBe(true);
    expect(await ui.withdrawRate(pg_vic, "C", "start")).toBe(false);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("n/a");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("n/a");
