        return roundsBy.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /**
     * The rate figure of an amount dated on the date for the grade: the amount at the rate in force then,
     * rounded by the date, with no floor; null when no rate is.
     */
    public BigDecimal figure(BigDecimal amount, String grade, LocalDate date) {
        return figure(amount, grade, date, null);
    }

    /** The rate figure of the claim with the id given, as {@link #figure(BigDecimal, String, LocalDate)} at the rate in force for it, see {@link #on(String, LocalDate, Long)}. */
    public BigDecimal figure(BigDecimal amount, String grade, LocalDate date, Long claimId) {
        return RateService.due(amount, on(grade, date, claimId), rounding(date));
    }

    /** A live due held up to the floor in force on the date: the greater of the two; null when the due is. */
    public BigDecimal floored(BigDecimal due, LocalDate date) {
        BigDecimal floor = settings.floor(date);
        return due == null || floor == null || due.compareTo(floor) >= 0 ? due : floor;
    }

    /**
     * The late charge on a figure of a claim due by the due-by: for every full 30 days from its due-by to the
     * sheet's today, the late percent in force on that boundary date (the due-by plus 30, 60, 90 ... days) of
     * the figure plus the charges of the boundaries before it (compounding), each rounded by the date its claim's rounding goes by, added up; a boundary whose percent is
     * 0.00 adds nothing. 0.00 when not a full 30 days overdue.
     */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate roundsBy) {
        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / LATE_PERIOD_DAYS : 0;
        RoundingMode rounding = rounding(roundsBy);
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = settings.latePct(dueBy.plusDays(n * LATE_PERIOD_DAYS));
            if (pct.signum() != 0) {
                charge = charge.add(RateService.due(figure.add(charge), pct, rounding));
            }
        }
        return charge;
    }
